<?php
require_once __DIR__.'/includes/auth.php';require_permission('dashboard');$pdo=db();
function sql_dump(PDO $pdo): string {$out="-- Barangay Information System local backup\n-- Generated: ".date('c')."\nSET FOREIGN_KEY_CHECKS=0;\n\n";$tables=$pdo->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);foreach($tables as $table){$safe=str_replace('`','``',$table);$out.="DROP TABLE IF EXISTS `{$safe}`;\n";$create=$pdo->query("SHOW CREATE TABLE `{$safe}`")->fetch();$out.=$create['Create Table'].";\n\n";$rows=$pdo->query("SELECT * FROM `{$safe}`")->fetchAll();foreach($rows as $row){$cols=array_map(fn($c)=>'`'.$c.'`',array_keys($row));$vals=array_map(fn($v)=>$v===null?'NULL':$pdo->quote((string)$v),array_values($row));$out.="INSERT INTO `{$safe}` (".implode(',',$cols).") VALUES (".implode(',',$vals).");\n";}$out.="\n";}return $out."SET FOREIGN_KEY_CHECKS=1;\n";}
if(isset($_GET['download'])){$dump=sql_dump($pdo);$encrypted=(int)($_GET['encrypted']??1)===1;$filename='barangay-backup-'.date('Y-m-d-His').($encrypted?'.sql.enc':'.sql');$payload=$dump;$key=getenv('BACKUP_ENCRYPTION_KEY')?:'';if($encrypted&&$key!==''){$iv=random_bytes(16);$payload='BIS-AES256\n'.base64_encode($iv)."\n".base64_encode(openssl_encrypt($dump,'aes-256-cbc',hash('sha256',$key,true),OPENSSL_RAW_DATA,$iv));}$pdo->prepare('INSERT INTO backup_logs (file_name,created_by,file_size) VALUES (?,?,?)')->execute([$filename,current_user()['id'],strlen($payload)]);audit_action('backup_created','backup_logs',(int)$pdo->lastInsertId(),$filename);header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="'.$filename.'"');header('Content-Length: '.strlen($payload));echo $payload;exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->prepare('UPDATE backup_settings SET enabled=?,frequency=?,encrypted=? WHERE id=1')->execute([(int)isset($_POST['enabled']),$_POST['frequency'],(int)isset($_POST['encrypted'])]);audit_action('backup_policy_updated','backup_settings',1,$_POST['frequency']);flash('success','Backup policy saved.');redirect('backup.php');}
$settings=$pdo->query('SELECT * FROM backup_settings WHERE id=1')->fetch();$logs=$pdo->query('SELECT b.*,u.full_name FROM backup_logs b LEFT JOIN users u ON u.id=b.created_by ORDER BY b.created_at DESC LIMIT 20')->fetchAll();$pageTitle='Backups';$activePage='backup';require __DIR__.'/partials/header.php';
?><section class="section-heading"><div><div class="eyebrow">Administration / Recovery</div><h1>Data backups</h1><p>Download a complete local backup for restoration and keep an audit trail of every backup.</p></div><a class="primary-button" href="backup.php?download=1&encrypted=1">⇩ Download encrypted backup</a></section><div class="priority-banner retention-safe"><span class="priority-icon">✓</span><div><strong>Encrypted backup support</strong><small>Set BACKUP_ENCRYPTION_KEY in Apache/PHP before using encrypted backups. Keep the key separately from the backup file.</small></div><a href="backup.php?download=1&encrypted=0">Download SQL</a></div><section class="panel form-panel"><div class="card-header"><div><div class="eyebrow">Backup policy</div><h2>Automation-ready settings</h2><p class="login-copy">The endpoint can be called by Windows Task Scheduler or cron. Manual payment handling is outside this module.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><label class="check-field"><input type="checkbox" name="enabled" <?= $settings['enabled']?'checked':'' ?>> Enable scheduled backup policy</label><label>Frequency<select name="frequency"><option value="daily" <?= $settings['frequency']==='daily'?'selected':'' ?>>Daily</option><option value="weekly" <?= $settings['frequency']==='weekly'?'selected':'' ?>>Weekly</option></select></label><label class="check-field"><input type="checkbox" name="encrypted" <?= $settings['encrypted']?'checked':'' ?>> Prefer encrypted backup files</label><div class="form-actions"><button class="primary-button">Save backup policy</button></div></form></section><section class="panel table-panel"><div class="table-toolbar"><div><div class="eyebrow">Backup history</div><h2>Recent backups</h2></div><span class="muted"><?= count($logs) ?> logged backups</span></div><div class="table-wrap"><table><thead><tr><th>File name</th><th>Created by</th><th>Size</th><th>Date</th></tr></thead><tbody><?php foreach($logs as $log): ?><tr><td class="mono"><?= h($log['file_name']) ?></td><td><?= h($log['full_name']??'Unknown') ?></td><td><?= h(number_format((int)$log['file_size']/1024,1)) ?> KB</td><td class="muted"><?= h(date('M d, Y h:i A',strtotime($log['created_at']))) ?></td></tr><?php endforeach; ?><?php if(!$logs): ?><tr><td colspan="4" class="muted">No backups have been downloaded yet.</td></tr><?php endif; ?></tbody></table></div></section><?php require __DIR__.'/partials/footer.php'; ?>
